    maisons: ["la identidad y la apariencia", "el dinero y los recursos", "la comunicación y el entorno cercano", "la familia y los orígenes", "la creatividad y los amores", "el trabajo cotidiano y la salud", "la pareja y las asociaciones", "las transformaciones y la herencia", "los viajes y el conocimiento", "la carrera y la reputación", "las amistades y los proyectos colectivos", "la interioridad y el inconsciente"],
    style: ["con impulso, franqueza e impaciencia", "con constancia, sensualidad y necesidad de seguridad", "con curiosidad, agilidad y gusto por el intercambio", "con sensibilidad, memoria y necesidad de proteger", "con calor, orgullo y generosidad", "con precisión, sentido del detalle y reserva", "con tacto, búsqueda de armonía y vacilación", "con intensidad, profundidad y secreto", "con entusiasmo, amplitud de miras y franqueza", "con seriedad, ambición y contención", "con independencia, originalidad y distancia", "con imaginación, empatía y vaguedad"],
    soleil: ["Una identidad que se construye en la acción: primero avanza, luego reflexiona, y soporta mal esperar.", "Una identidad que busca la estabilidad y lo concreto: lo que cuenta debe durar, tocarse, saborearse.", "Una identidad móvil, alimentada de intercambios y curiosidad: necesita comprender y contar.", "Una identidad vuelta hacia el vínculo y la memoria: proteger y ser protegido, guardar lo que importa.", "Una identidad que necesita brillar y dar: el reconocimiento le impulsa, la indiferencia le apaga.", "Una identidad que se realiza en el trabajo bien hecho: observar, ordenar, mejorar, sin ruido.", "Una identidad que se busca en la relación: el otro es el espejo, la armonía es la meta.", "Una identidad entera, que no hace nada a medias: compromiso total o nada.", "Una identidad que necesita horizonte: aprender, partir, creer en algo más grande.", "Una identidad que se construye a largo plazo: responsabilidad, paciencia, resultados.", "Una identidad apegada a su libertad: pensar de otro modo, pertenecer sin disolverse.", "Una identidad porosa e imaginativa: sentir antes de saber, y a veces perderse en el otro."],
    lune: ["Emociones vivas y breves: la cólera sube rápido y baja igual de rápido; necesita moverse para digerir.", "Emociones estables que piden comodidad: un lugar, unas costumbres, un cuerpo tranquilizado.", "Emociones que pasan por las palabras: hablar calma, el silencio inquieta.", "Emociones profundas y cambiantes, muy apegadas al hogar y a los recuerdos: el signo donde la Luna está más a gusto.", "Emociones teatrales y cálidas: necesita ser visto y admirado para sentirse bien.", "Emociones contenidas, analizadas, a veces ansiosas: el orden y la utilidad le apaciguan.", "Emociones que buscan el acuerdo: el conflicto le cuesta, la belleza le repara.", "Emociones intensas, celosas de su intimidad: todo o nada, y la memoria de las heridas.", "Emociones optimistas que necesitan espacio: el encierro, incluso afectivo, le ahoga.", "Emociones contenidas, pudorosas, que desconfían de la efusión: la seguridad pasa por el control.", "Emociones a distancia, observadas más que vividas: la amistad le tranquiliza más que la fusión.", "Emociones absorbentes, muy receptivas a las de los demás: necesita soledad para reencontrarse."],
    ascendant: ["Llega rápido y de frente: se le percibe directo, enérgico, a veces brusco.", "Inspira calma y solidez: se le percibe sereno, sensual, difícil de alterar.", "Atrae por la palabra y la viveza: se le percibe ligero, curioso, inasible.", "Se acerca con prudencia y dulzura: se le percibe reservado, atento, protector.", "Entra en escena: se le percibe seguro, cálido, un poco imperioso.", "Observa antes de hablar: se le percibe discreto, preciso, exigente.", "Pone a gusto: se le percibe cortés, seductor, deseoso de agradar.", "Intriga: se le percibe intenso, reservado, un poco inquietante.", "Irradia entusiasmo: se le percibe abierto, franco, a veces torpe.", "Impone respeto: se le percibe serio, reservado, fiable.", "Sorprende: se le percibe original, distante, independiente.", "Enternece: se le percibe dulce, soñador, difícil de definir."],
    venus: ["Ama rápido, con ardor, y se cansa de lo que no resiste.", "Ama con los sentidos y con la duración: fidelidad, placeres sencillos, posesividad.", "Ama hablando: la complicidad intelectual cuenta tanto como la atracción.", "Ama protegiendo: ternura, hogar, apego profundo y un poco ansioso.", "Ama con brillo: generosidad, celos, necesidad de ser admirado.", "Ama con discreción y entrega: las pruebas cuentan más que las palabras.", "Ama el amor mismo: romanticismo, estética, necesidad de una pareja para sentirse completo.", "Ama a fondo: pasión, exclusividad, dificultad para perdonar.", "Ama en libertad: la aventura y la sinceridad antes que la seguridad.", "Ama con reserva y seriedad: despacio, pero para mucho tiempo.", "Ama en amistad: independencia, originalidad, desconfianza hacia la fusión.", "Ama entregándose: compasión, idealización, riesgo de olvidarse de sí."],
    mars: ["Un deseo directo y rápido, una combatividad franca: se lanza, se enfada, olvida.", "Un deseo sensual y tenaz, una cólera lenta pero duradera.", "Un deseo mental y juguetón: las palabras seducen, la rutina mata.", "Un deseo ligado a los sentimientos, una agresividad indirecta: se defiende más que ataca.", "Un deseo orgulloso y demostrativo: quiere conquistar y ser elegido.", "Un deseo controlado, atento al detalle: actúa con método, critica más que grita.", "Un deseo que duda: busca el acuerdo y evita el enfrentamiento, a veces demasiado.", "Un deseo poderoso y secreto, una voluntad implacable: el signo tradicional de Marte.", "Un deseo entusiasta e impaciente: lo quiere todo, ya, y en otra parte.", "Un deseo controlado y ambicioso: el esfuerzo largo no le asusta.", "Un deseo independiente e imprevisible: rechaza lo que le imponen.", "Un deseo difuso y soñador: la voluntad se diluye, la imaginación compensa."],
    intro_planete: { mercury: "Mercurio describe el pensamiento y la palabra", jupiter: "Júpiter describe la confianza y la expansión", saturn: "Saturno describe los límites y la disciplina", uranus: "Urano describe la necesidad de ruptura y de originalidad", neptune: "Neptuno describe el imaginario y el ideal", pluto: "Plutón describe las transformaciones profundas" },
    mc: ["Una carrera de iniciativa y competición.", "Una carrera de construcción paciente y de bienes tangibles.", "Una carrera de intercambios, escritos y movimiento.", "Una carrera de cuidado, acogida o transmisión.", "Una carrera de representación y de dirección.", "Una carrera de servicio preciso y de pericia.", "Una carrera de relación, de derecho o de estética.", "Una carrera de investigación, de crisis o de transformación.", "Una carrera de enseñanza, de viaje o de convicción.", "Una carrera de autoridad y de largo aliento.", "Una carrera de innovación o de colectivo.", "Una carrera de ayuda, de arte o de imaginario."],
