    planetes: { sun: "Sole", moon: "Luna", mercury: "Mercurio", venus: "Venere", mars: "Marte", jupiter: "Giove", saturn: "Saturno", uranus: "Urano", neptune: "Nettuno", pluto: "Plutone", asc: "Ascendente", mc: "Medio Cielo" },
    phases: ["Luna nuova", "Luna crescente", "Primo quarto", "Gibbosa crescente", "Luna piena", "Gibbosa calante", "Ultimo quarto", "Luna calante"],
    aspects: { conj: "congiunzione", opp: "opposizione", tri: "trigono", sq: "quadratura", sex: "sestile" },
    maisons: ["l’identità e l’aspetto", "il denaro e le risorse", "la comunicazione e le persone vicine", "la famiglia e le origini", "la creatività e gli amori", "il lavoro quotidiano e la salute", "la coppia e le associazioni", "le trasformazioni e l’eredità", "i viaggi e la conoscenza", "la carriera e la reputazione", "le amicizie e i progetti collettivi", "l’interiorità e l’inconscio"],
    style: ["con slancio, franchezza e impazienza", "con costanza, sensualità e bisogno di sicurezza", "con curiosità, agilità e gusto per lo scambio", "con sensibilità, memoria e bisogno di proteggere", "con calore, fierezza e generosità", "con precisione, senso del dettaglio e riserbo", "con tatto, ricerca di armonia ed esitazione", "con intensità, profondità e segretezza", "con entusiasmo, larghezza di vedute e franchezza", "con serietà, ambizione e ritegno", "con indipendenza, originalità e distacco", "con immaginazione, empatia e vaghezza"],
    soleil: ["Un’identità che si costruisce nell’azione: prima avanzate, poi riflettete, e sopportate male l’attesa.", "Un’identità che cerca la stabilità e il concreto: ciò che conta deve durare, toccarsi, gustarsi.", "Un’identità mobile, nutrita di scambi e di curiosità: avete bisogno di capire e di raccontare.", "Un’identità rivolta al legame e alla memoria: proteggere ed essere protetti, conservare ciò che conta.", "Un’identità che ha bisogno di brillare e di dare: il riconoscimento vi sostiene, l’indifferenza vi spegne.", "Un’identità che si realizza nel lavoro ben fatto: osservare, selezionare, migliorare, senza rumore.", "Un’identità che si cerca nella relazione: l’altro è lo specchio, l’armonia è la meta.", "Un’identità intera, che non fa nulla a metà: impegno totale o niente.", "Un’identità che ha bisogno di orizzonte: imparare, partire, credere in qualcosa di più grande.", "Un’identità che si costruisce sul lungo periodo: responsabilità, pazienza, risultati.", "Un’identità che tiene alla propria libertà: pensare diversamente, appartenere senza dissolversi.", "Un’identità porosa e immaginativa: sentire prima di sapere, e a volte perdersi nell’altro."],
    lune: ["Emozioni vive e brevi: la collera sale in fretta e ricade altrettanto in fretta; avete bisogno di muovervi per digerire.", "Emozioni stabili che chiedono comodità: un luogo, delle abitudini, un corpo rassicurato.", "Emozioni che passano dalle parole: parlare calma, il silenzio inquieta.", "Emozioni profonde e mutevoli, molto legate alla casa e ai ricordi: il segno in cui la Luna è più a suo agio.", "Emozioni teatrali e calorose: avete bisogno di essere visti e ammirati per sentirvi bene.", "Emozioni contenute, analizzate, a volte ansiose: l’ordine e l’utilità vi placano.", "Emozioni che cercano l’accordo: il conflitto vi costa, la bellezza vi ripara.", "Emozioni intense, gelose della propria intimità: tutto o niente, e la memoria delle ferite.", "Emozioni ottimiste che hanno bisogno di spazio: la chiusura, anche affettiva, vi soffoca.", "Emozioni trattenute, pudiche, che diffidano dell’effusione: la sicurezza passa dal controllo.", "Emozioni a distanza, osservate più che vissute: l’amicizia vi rassicura più della fusione.", "Emozioni assorbenti, molto ricettive a quelle degli altri: avete bisogno di solitudine per ritrovarvi."],
    ascendant: ["Arrivate in fretta e di fronte: vi si percepisce diretti, energici, a volte bruschi.", "Ispirate calma e solidità: vi si percepisce posati, sensuali, difficili da scuotere.", "Catturate con la parola e la vivacità: vi si percepisce leggeri, curiosi, inafferrabili.", "Vi avvicinate con prudenza e dolcezza: vi si percepisce riservati, attenti, protettivi.", "Entrate in scena: vi si percepisce sicuri, calorosi, un po’ imperiosi.", "Osservate prima di parlare: vi si percepisce discreti, precisi, esigenti.", "Mettete a proprio agio: vi si percepisce cortesi, seducenti, desiderosi di piacere.", "Incuriosite: vi si percepisce intensi, riservati, un po’ inquietanti.", "Irradiate entusiasmo: vi si percepisce aperti, franchi, a volte maldestri.", "Imponete rispetto: vi si percepisce seri, riservati, affidabili.", "Sorprendete: vi si percepisce originali, distanti, indipendenti.", "Intenerite: vi si percepisce dolci, sognatori, difficili da inquadrare."],
    venus: ["Amate in fretta, con foga, e vi stancate di ciò che non resiste.", "Amate con i sensi e con la durata: fedeltà, piaceri semplici, possessività.", "Amate parlando: la complicità intellettuale conta quanto l’attrazione.", "Amate proteggendo: tenerezza, casa, attaccamento profondo e un po’ ansioso.", "Amate con panache: generosità, gelosia, bisogno di essere ammirati.", "Amate con discrezione e dedizione: le prove contano più delle parole.", "Amate l’amore stesso: romanticismo, estetica, bisogno di un partner per sentirvi completi.", "Amate fino in fondo: passione, esclusività, difficoltà a perdonare.", "Amate in libertà: l’avventura e la sincerità prima della sicurezza.", "Amate con riserbo e serietà: lentamente, ma per molto tempo.", "Amate in amicizia: indipendenza, originalità, diffidenza verso la fusione.", "Amate donandovi: compassione, idealizzazione, rischio di dimenticare voi stessi."],
    mars: ["Un desiderio diretto e rapido, una combattività franca: vi buttate, vi arrabbiate, dimenticate.", "Un desiderio sensuale e tenace, una collera lenta ma durevole.", "Un desiderio mentale e giocoso: le parole seducono, la routine uccide.", "Un desiderio legato ai sentimenti, un’aggressività indiretta: vi difendete più di quanto attacchiate.", "Un desiderio fiero e dimostrativo: volete conquistare ed essere scelti.", "Un desiderio controllato, attento al dettaglio: agite con metodo, criticate più di quanto gridiate.", "Un desiderio che esita: cercate l’accordo ed evitate lo scontro, a volte troppo.", "Un desiderio potente e segreto, una volontà implacabile: il segno tradizionale di Marte.", "Un desiderio entusiasta e impaziente: volete tutto, subito, altrove.", "Un desiderio controllato e ambizioso: lo sforzo lungo non vi spaventa.", "Un desiderio indipendente e imprevedibile: rifiutate ciò che vi viene imposto.", "Un desiderio diffuso e sognante: la volontà si diluisce, l’immaginazione compensa."],
